custom_qss:
/* ============================================================
   ACID — acid lime on near-black. High-saturation neon, rounded,
   borderless. Signature: a bright lime sheen stop baked high inside
   every vertical gradient (fake glow), hard large radii, and
   uppercase letter-spaced labels. Distinct from the spring-greens.
   ============================================================ */

* { border: none; background-color: transparent !important; color: #e8f5d8; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget { background: transparent !important; border: none; }

QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #131c08, stop:0.4 #0a0f06, stop:0.75 #060903, stop:1 #0c1207) !important;
}
QDialog { background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #131c08, stop:0.5 #0c1207, stop:1 #050803) !important; }

QMenuBar { background: transparent !important; }
QMenuBar::item { padding: 5px 13px; border-radius: 8px; background: transparent !important; color: #7d9c4a; }
QMenuBar::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #2c4218, stop:1 #4a661f) !important; color: #e8f5d8; }
QMenuBar::item:disabled { color: #4f6630; }

QMenu { background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #131c08, stop:1 #0a0f06) !important; border-radius: 14px; padding: 7px; }
QMenu::item { padding: 7px 26px 7px 14px; border-radius: 9px; background: transparent !important; color: #e8f5d8; }
QMenu::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:1 #3d5200) !important; color: #0a0f06 !important; font-weight: 600; }
QMenu::item:disabled { color: #4f6630; }
QMenu::separator { height: 1px; background: #1e2c10; margin: 6px 10px; border-radius: 1px; }

QToolBar { background: transparent !important; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #1e2c10; width: 2px; margin: 6px 5px; border-radius: 1px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 10px; border-radius: 9px; color: #7d9c4a; }
QToolBar QToolButton:hover, QToolButton:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1e2c10, stop:1 #0f1708) !important; color: #c8ff33; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed, QToolButton:checked, QToolButton:pressed { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:1 #3d5200) !important; color: #0a0f06 !important; }

QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #1e2c10, stop:0.3 #16210b, stop:1 #0f1708) !important;
    border-radius: 13px; padding: 8px 22px; color: #e8f5d8; font-weight: 600;
}
QPushButton:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #c8ff33, stop:0.12 #9ae600, stop:0.55 #7ab800, stop:1 #3d5200) !important; color: #0a0f06 !important; }
QPushButton:pressed { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #0f1708, stop:0.5 #1e2c10, stop:0.9 #9ae600, stop:1 #3d5200) !important; color: #0a0f06 !important; }
QPushButton:checked { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:0.5 #7ab800, stop:1 #c8ff33) !important; color: #0a0f06 !important; }
QPushButton:disabled { background: #0c1207 !important; color: #4f6630 !important; }

QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #131c08, stop:1 #060903) !important;
    border-radius: 11px; padding: 6px 12px; color: #c8ff33;
    selection-background-color: #9ae600; selection-color: #0a0f06;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1e2c10, stop:1 #131c08) !important; color: #c8ff33 !important; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #4f6630 !important; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1e2c10, stop:1 #0f1708) !important; border-radius: 11px; padding: 6px 12px; color: #e8f5d8; }
QComboBox:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #2c4218, stop:1 #16210b) !important; }
QComboBox:focus { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #9ae600, stop:1 #3d5200) !important; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: qlineargradient(x1:0, y1:0, x2:0.3, y2:1, stop:0 #131c08, stop:1 #0a0f06) !important; border-radius: 13px; padding: 6px; selection-background-color: #9ae600; selection-color: #0a0f06; }

QCheckBox, QRadioButton { color: #e8f5d8; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator { width: 20px; height: 20px; border-radius: 6px; background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #1e2c10, stop:1 #0f1708) !important; }
QRadioButton::indicator { border-radius: 10px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #2c4218, stop:1 #1e2c10) !important; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: qlineargradient(x1:0, y1:0, x2:1, y2:1, stop:0 #9ae600, stop:1 #3d5200) !important; }

QTabBar::tab { background: transparent !important; color: #7d9c4a; padding: 9px 18px; border-radius: 11px; margin: 0 1px; }
QTabBar::tab:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #16210b, stop:1 #0c1207) !important; color: #c8ff33; }
QTabBar::tab:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:0.5 #7ab800, stop:1 #c8ff33) !important; color: #0a0f06 !important; font-weight: 700; letter-spacing: 0.5px; }
QTabWidget::pane { border: none; background: #0a0f06; }

QDockWidget { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #131c08, stop:0.6 #0f1708, stop:1 #0c1207) !important; border: none; }
QDockWidget::title { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #16210b, stop:1 #0c1207) !important; border-radius: 8px; margin: 3px; padding: 7px 11px; color: #b6d68f; font-size: 11px; font-weight: 700; letter-spacing: 1.5px; }
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: none; border-radius: 6px; padding: 3px; icon-size: 13px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #1e2c10 !important; }

QGroupBox { background: transparent !important; border: none; border-radius: 12px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 9px; color: #9ae600; font-weight: 700; letter-spacing: 1.2px; background: #0a0f06; }

QAbstractItemView { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #0c1207, stop:1 #060903) !important; border: none; border-radius: 12px; outline: none; alternate-background-color: #0a0f06; selection-background-color: #9ae600; selection-color: #0a0f06; }
QAbstractItemView::item { padding: 6px 10px; border: none; color: #e8f5d8; border-radius: 8px; }
QAbstractItemView::item:hover { background: #131c08 !important; }
QAbstractItemView::item:selected { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:1 #3d5200) !important; color: #0a0f06 !important; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #0c1207 !important; border: none; padding: 7px 11px; color: #7d9c4a; font-size: 11px; font-weight: 700; letter-spacing: 1px; }

QScrollBar:vertical { background: transparent; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #2c4218, stop:1 #1e2c10) !important; border-radius: 6px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #9ae600, stop:1 #3d5200) !important; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: transparent; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #2c4218, stop:1 #1e2c10) !important; border-radius: 6px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #9ae600, stop:1 #3d5200) !important; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #060903; border: none; height: 6px; border-radius: 3px; }
QSlider::sub-page:horizontal { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3d5200, stop:1 #9ae600) !important; border-radius: 3px; }
QSlider::add-page:horizontal { background: #060903; border-radius: 3px; }
QSlider::handle:horizontal { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #c8ff33, stop:1 #9ae600) !important; width: 16px; height: 16px; margin: -6px 0; border: none; border-radius: 9px; }
QSlider::handle:horizontal:hover { background: #ffffff !important; }
QSlider::groove:vertical { background: #060903; border: none; width: 6px; border-radius: 3px; }
QSlider::sub-page:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #3d5200, stop:1 #9ae600) !important; border-radius: 3px; }
QSlider::handle:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #c8ff33, stop:1 #9ae600) !important; width: 16px; height: 16px; margin: 0 -6px; border: none; border-radius: 9px; }

QProgressBar { background: #060903; border: none; border-radius: 8px; text-align: center; color: #b6d68f; font-size: 11px; min-height: 15px; }
QProgressBar::chunk { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #3d5200, stop:0.5 #9ae600, stop:1 #c8ff33) !important; border-radius: 6px; }

QStatusBar { background: transparent !important; color: #7d9c4a; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #131c08, stop:1 #0a0f06) !important; border: 1px solid #1e2c10; border-radius: 9px; padding: 7px 11px; color: #e8f5d8; }
QSplitter::handle { background: #1e2c10; border-radius: 2px; }
QSplitter::handle:hover { background: #9ae600; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #060903 !important; border: none; border-radius: 12px; outline: none; }
